svg.script:
(function () {
  // Lentille mince convergente f' = 50 mm, échelle 1,8 px par mm, lentille en x = 172, axe en y = 150
  var K = 1.8, L = 172, Y = 150, F = 50, H = 40, BORD = 480;
  var OA_QUESTION = -75;
  var $ = function (id) { return document.getElementById(id); };
  var svg = document.documentElement;

  function nombre(v, dec) {
    var s = (Math.round(v * Math.pow(10, dec)) / Math.pow(10, dec)).toFixed(dec).replace(".", ",");
    return (v > 0 ? "+" : v < 0 ? "−" : "") + s.replace("-", "");
  }
  function droite(x1, y1, x2, y2, x) { return y1 + (y2 - y1) * (x - x1) / (x2 - x1); }
  function seg(pts) { return "M" + pts.map(function (p) { return p[0].toFixed(1) + " " + p[1].toFixed(1); }).join(" L"); }

  function dessiner(OA) {
    var xo = L + OA * K, yB = Y - H;
    $("obj").setAttribute("x1", xo); $("obj").setAttribute("x2", xo);
    $("zone").setAttribute("x", xo - 20);
    $("oa").setAttribute("x", xo - 6); $("ob").setAttribute("x", xo - 7);

    var infini = Math.abs(OA + F) < 1.2;
    var OAp = infini ? Infinity : 1 / (1 / F + 1 / OA);
    var g = infini ? Infinity : OAp / OA;
    var xi = L + OAp * K, yi = Y - H * g;

    // Rayon 1 : parallèle à l'axe, puis passe par F'
    var y1bord = droite(L, yB, L + F * K, Y, BORD);
    $("r1").setAttribute("d", seg([[xo, yB], [L, yB], [BORD, y1bord]]));
    // Rayon 2 : passe par O sans être dévié
    $("r2").setAttribute("d", seg([[xo, yB], [BORD, droite(xo, yB, L, Y, BORD)]]));
    // Rayon 3 : passe par F (ou semble en venir), puis ressort parallèle
    var y3 = droite(xo, yB, L - F * K, Y, L);
    if (!isFinite(y3) || Math.abs(y3) > 4000) y3 = Y + 4000;
    $("r3").setAttribute("d", infini ? "" : seg([[xo, yB], [L, y3], [BORD, y3]]));

    // Prolongements virtuels (en pointillés) si l'image est virtuelle
    var virtuelle = !infini && OAp < 0;
    $("v1").setAttribute("d", virtuelle ? seg([[L, yB], [xi, yi]]) : "");
    $("v2").setAttribute("d", virtuelle ? seg([[L, Y], [xi, yi]]) : "");
    $("v3").setAttribute("d", virtuelle ? seg([[L, y3], [xi, yi]]) : "");

    var img = $("imgfl");
    if (infini) {
      $("image").setAttribute("visibility", "hidden");
    } else {
      $("image").setAttribute("visibility", "visible");
      img.setAttribute("x1", xi); img.setAttribute("x2", xi);
      img.setAttribute("y2", yi + (yi > Y ? -2 : 2));
      img.setAttribute("stroke-dasharray", virtuelle ? "7 5" : "none");
      $("ia").setAttribute("x", xi - 30); $("ia").setAttribute("y", yi > Y ? Y - 10 : Y + 24);
      $("ib").setAttribute("x", xi - 32); $("ib").setAttribute("y", yi > Y ? yi + 24 : yi - 10);
    }

    // Mesures et nature de l'image
    if (infini) {
      $("mesures").textContent = "OA = " + nombre(OA, 0) + " mm : l'objet est au foyer F";
      $("nature").textContent = "Image rejetée à l'infini";
    } else {
      $("mesures").textContent = "OA = " + nombre(OA, 0) + " mm  ·  OA' = " + nombre(OAp, 0) + " mm  ·  γ = " + nombre(g, 1);
      var taille = Math.abs(g);
      var t = taille > 1.05 ? (taille < 9.95 ? nombre(taille, 1).replace("+", "").replace(",0", "") + " fois plus grande" : "beaucoup plus grande")
            : taille < 0.95 ? (taille >= 0.105 ? nombre(1 / taille, 1).replace("+", "").replace(",0", "") + " fois plus petite" : "beaucoup plus petite") : "de même taille";
      $("nature").textContent = "Image " + (virtuelle ? "virtuelle, droite" : "réelle, renversée") + ", " + t;
    }
  }

  function finirAnimations() {
    ["r1", "r2", "r3"].forEach(function (id) { $(id).classList.remove("trace"); });
    Array.prototype.forEach.call(document.querySelectorAll(".anim"), function (el) { el.classList.remove("anim"); });
  }

  // Glisser l'objet (souris ou doigt)
  var poignee = $("poignee"), actif = false;
  function versSVG(e) {
    var p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  }
  poignee.addEventListener("pointerdown", function (e) {
    actif = true; finirAnimations(); $("aide").setAttribute("visibility", "hidden");
    poignee.setPointerCapture(e.pointerId); e.preventDefault();
  });
  poignee.addEventListener("pointermove", function (e) {
    if (!actif) return;
    var x = Math.max(12, Math.min(L - 14, versSVG(e).x));
    oaCourant = (x - L) / K;
    dessiner(oaCourant);
  });
  function lacher() { if (actif) verifierDefi(); actif = false; }
  poignee.addEventListener("pointerup", lacher);
  poignee.addEventListener("pointercancel", lacher);

  // Revenir à la question et rejouer le tracé
  $("rejouer").addEventListener("click", function () {
    oaCourant = OA_QUESTION; defi = -1; $("defi").setAttribute("visibility", "hidden");
    dessiner(OA_QUESTION);
    ["r1", "r2", "r3"].forEach(function (id) {
      var el = $(id); el.classList.remove("trace"); void el.getBoundingClientRect(); el.classList.add("trace");
    });
    var im = $("image"); im.classList.remove("anim"); void im.getBoundingClientRect(); im.classList.add("anim");
  });

  // ---------- Mode défi : placer l'objet pour obtenir l'image demandée ----------
  var DEFIS = [
    { texte: "une image réelle 1,5 fois plus grande", cible: -250 / 3, ok: function (oa, g) { return isFinite(g) && g < 0 && Math.abs(Math.abs(g) - 1.5) < 0.12; } },
    { texte: "une image virtuelle 2 fois plus grande", cible: -25, ok: function (oa, g) { return isFinite(g) && g > 0 && Math.abs(g - 2) < 0.15; } },
    { texte: "une image rejetée à l'infini", cible: -50, ok: function (oa) { return Math.abs(oa + F) < 2.5; } }
  ];
  var defi = -1, oaCourant = OA_QUESTION;
  function afficherDefi() {
    $("defi").setAttribute("visibility", "visible");
    $("defifond").setAttribute("stroke", "#d9b26f");
    $("defi1").textContent = "🎯 Défi " + (defi + 1) + "/" + DEFIS.length + " : place l'objet pour obtenir";
    $("defi2").textContent = DEFIS[defi].texte;
  }
  function verifierDefi() {
    if (defi < 0) return;
    var infini = Math.abs(oaCourant + F) < 1.2;
    var g = infini ? Infinity : (1 / (1 / F + 1 / oaCourant)) / oaCourant;
    if (!DEFIS[defi].ok(oaCourant, g)) return;
    oaCourant = DEFIS[defi].cible; dessiner(oaCourant);   // on aligne sur la valeur exacte
    $("defifond").setAttribute("stroke", "#5fd08a");
    $("defi1").textContent = "✓ Bravo !";
    var fini = defi === DEFIS.length - 1;
    $("defi2").textContent = fini ? "Tous les défis sont réussis 🎉" : "Défi suivant dans un instant…";
    var suivant = defi + 1; defi = fini ? -1 : -2;
    if (!fini) setTimeout(function () { defi = suivant; afficherDefi(); }, 1600);
  }
  $("bdefi").addEventListener("click", function () {
    finirAnimations(); $("aide").setAttribute("visibility", "visible");
    defi = 0; afficherDefi();
  });

  // ---------- Réponse fausse de l'élève, tracée en rouge ----------
  // Numéros = position de la réponse dans q.choix (questions-U42.js)
  var ERREURS = {
    1: { oap: 37.5, val: "OA' = +37,5 mm", pourquoi: "Une image réelle se forme toujours après F'." },
    2: { oap: -150, val: "OA' = −150 mm", pourquoi: "Les rayons se croisent après la lentille : image réelle." },
    3: { oap: 30, val: "OA' = +30 mm", pourquoi: "Erreur de signe : l'objet réel a OA = −75 mm, pas +75." }
  };
  var m = /faux=(\d)/.exec(location.hash);
  var err = m && ERREURS[m[1]];
  if (err) {
    svg.setAttribute("viewBox", "0 0 480 450");          // on agrandit pour la zone de bilan
    var xe = L + err.oap * K, dedans = xe > 30 && xe < BORD - 30;
    var xr = dedans ? xe : 10;
    $("errligne").setAttribute("x1", xr); $("errligne").setAttribute("x2", xr);
    if (!dedans) $("errligne").setAttribute("visibility", "hidden");
    $("errpoint").setAttribute("cx", xr);
    $("errtag").setAttribute("x", dedans ? xe : 12);
    $("errtag").setAttribute("text-anchor", dedans ? "middle" : "start");
    if (!dedans) $("errtag").textContent = "← ta réponse";
    $("errval").textContent = err.val;
    $("errpourquoi").textContent = "→ " + err.pourquoi;
    $("erreur").setAttribute("visibility", "visible");
    $("aide").setAttribute("visibility", "hidden");
  }

  dessiner(OA_QUESTION);
})();
